/**
 * Authentic Quaternius CC0 locomotion playback for glTF-skinned humanoids.
 *
 * Babylon's glTF importer links Skeleton.bones to TransformNodes, updating
 * the bone from its linked node every render. Animating the Bone directly is
 * discarded (the cause of Epoch's static T-pose). We drive linked nodes.
 *
 * Source clips: Quaternius Universal Animation Library, idle / walk / jog.
 * Data-only JSON is generated by tools/import-quaternius-walk.mjs.
 */
const B=globalThis.BABYLON;
const cache=new WeakMap();
const ASSET="./assets/animations/quaternius-locomotion.json?v=20261113h";

export async function loadLocomotion(scene){
 let p=cache.get(scene);
 if(!p){
  p=fetch(ASSET).then(async response=>{
   if(!response.ok)throw new Error("Movement clips unavailable: HTTP "+response.status);
   const data=await response.json();
   if(data?.version!==1||!data.clips?.idle||!data.clips?.walk||!data.clips?.run)
    throw Error("Invalid Quaternius locomotion data");
   return data;
  }).catch(error=>{cache.delete(scene);throw error});
  cache.set(scene,p);
 }
 return p;
}
const unprefix=name=>String(name||"").replace(/^epoch_\d+_/,"");
const Q=values=>new B.Quaternion(values[0],values[1],values[2],values[3]);
const safeQuaternion=q=>(q?.clone?.()||B.Quaternion.Identity()).normalize();
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));

function sample(track,time){
 const ts=track.times,vs=track.values,n=ts.length;
 if(n===1||time<=ts[0])return {from:vs[0],to:vs[0],alpha:0};
 if(time>=ts[n-1])return {from:vs[n-1],to:vs[n-1],alpha:0};
 let lo=0,hi=n-1;
 while(hi-lo>1){const mid=(lo+hi)>>1;if(ts[mid]<time)lo=mid;else hi=mid}
 const span=ts[hi]-ts[lo];
 return {from:vs[lo],to:vs[hi],alpha:span>0?clamp((time-ts[lo])/span,0,1):0};
}
function sampledQuaternion(track,time){
 const s=sample(track,time);
 return B.Quaternion.Slerp(Q(s.from),Q(s.to),s.alpha).normalize();
}
function sampledPosition(track,time){
 const s=sample(track,time),a=s.from,b=s.to,k=s.alpha;
 return new B.Vector3(a[0]+(b[0]-a[0])*k,a[1]+(b[1]-a[1])*k,a[2]+(b[2]-a[2])*k);
}

export function createLocomotionPlayer(scene,model,data){
 const nodes=new Map();
 for(const skeleton of model.skeletons||[]){
  for(const bone of skeleton.bones||[]){
   const node=bone.getTransformNode?.();
   if(node)nodes.set(unprefix(bone.name),node);
  }
 }
 // In rare Babylon export paths, links are exposed through scene nodes only.
 if(nodes.size<10){
  const walk=root=>{
   const name=unprefix(root.name);
   if(!nodes.has(name))nodes.set(name,root);
   for(const child of root.getChildren?.()||[])walk(child);
  };
  for(const root of model.rootNodes||[])walk(root);
 }
 const clipNames=["idle","walk","run"];
 const rest=new Map(),resolved={};
 for(const role of clipNames){
  const clip=data.clips[role];
  const tracks=[];
  for(const track of clip.tracks){
   // The glTF root carries the right-handed → left-handed conversion and
   // must not be overwritten by the source animation's exported root track.
   if(track.name==="root")continue;
   const node=nodes.get(track.name);
   if(!node)continue;
   let base=rest.get(track.name);
   if(!base){
    const rotation=node.rotationQuaternion?node.rotationQuaternion.clone():B.Quaternion.FromEulerVector(node.rotation);
    base={
     node,
     rotation:safeQuaternion(rotation),
     position:node.position.clone()
    };
    rest.set(track.name,base);
   }
   if(track.path==="rotation"){
    const relative=base.rotation.multiply(B.Quaternion.Inverse(Q(track.rest).normalize()));
    tracks.push({...track,base,relative});
   }else if(track.path==="translation"){
    tracks.push({...track,base});
   }
  }
  resolved[role]={duration:clip.duration,tracks};
 }
 const count=new Set(resolved.walk.tracks.map(t=>t.name));
 if(count.size<20)throw Error("Character rig doesn't match the Quaternius animation library (matched "+count.size+" bones)");

 let state="idle",phase=0,lastTime=null,fade=1,blendFrom=new Map();
 const DURATION={idle:.24,walk:.19,run:.14};
 const sampleTrack=(track,time)=>{
  if(track.path==="rotation"){
   const q=sampledQuaternion(track,time);
   return {rotation:track.relative.multiply(q).normalize()};
  }
  const p=sampledPosition(track,time);
  // Relative translations keep bone pivots in the character's rest pose.
  const initial=track.rest;
  return {position:track.base.position.add(new B.Vector3(p.x-initial[0],p.y-initial[1],p.z-initial[2]))};
 };
 const controller={
  matchedBones:count.size,
  get mode(){return state},
  get phase(){return phase},
  update(elapsedSeconds,mode="idle"){
   mode=resolved[mode]?mode:"idle";
   const dt=lastTime===null?0:clamp(elapsedSeconds-lastTime,0,.12);
   lastTime=elapsedSeconds;
   if(mode!==state){
    const from=resolved[state],to=resolved[mode];
    phase=to.duration*(phase/Math.max(.01,from.duration))%to.duration;
    state=mode;fade=0;
    blendFrom=new Map();
    for(const [name,base] of rest){
     blendFrom.set(name,{
      rotation:base.node.rotationQuaternion?.clone?.()||base.rotation.clone(),
      position:base.node.position.clone()
     });
    }
   }
   const clip=resolved[state];
   phase=(phase+dt)%Math.max(.0001,clip.duration);
   fade=Math.min(1,fade+dt/DURATION[state]);
   const blend=fade>=1?1:fade*fade*(3-2*fade);
   for(const track of clip.tracks){
    const {node}=track.base;
    const desired=sampleTrack(track,phase);
    if(desired.rotation){
     const prev=blendFrom.get(track.name)?.rotation;
     const value=prev&&blend<1?B.Quaternion.Slerp(prev,desired.rotation,blend):desired.rotation;
     if(node.rotationQuaternion)node.rotationQuaternion.copyFrom(value);
     else node.rotationQuaternion=value.clone();
    }else if(desired.position){
     const prev=blendFrom.get(track.name)?.position;
     const value=prev&&blend<1?B.Vector3.Lerp(prev,desired.position,blend):desired.position;
     node.position.copyFrom(value);
    }
   }
  },
  reset(){
   for(const base of rest.values()){
    if(base.node.rotationQuaternion)base.node.rotationQuaternion.copyFrom(base.rotation);
    else base.node.rotationQuaternion=base.rotation.clone();
    base.node.position.copyFrom(base.position);
   }
  }
 };
 return controller;
}
